import socket
import sys
import shlex
import time
import logging


class ParagonxAPI(object):
    _PARAGON_READY = "__PARAGON__"
    _PARAGON_ERROR = "ERROR: "

    def __init__(self, inst_address, gui_address, gui_port=9000, inst_port=9990, rc=1):
        self._socket = socket.socket()
        self._inst_address = inst_address
        self._gui_address = gui_address
        self._gui_port = gui_port
        self._inst_port = inst_port
        self._rc = rc
        self._lastErr = ""
        self._connected = False
        self._debug_info = False

    def _debug(self, msg):
        if self._debug_info:
            logging.info(msg)
            sys.stdout.flush()

    def _check_for_error(self, label):
        if len(self._lastErr) > 0:
            raise Exception("%s : %s" % (label, self._lastErr))

    def _gui_connect(self):
        logging.info("Connecting to %s:%s... " % (self._gui_address, self._gui_port))

        # Create a new socket and connect to the GUI
        self._socket.connect((self._gui_address, self._gui_port))

        logging.info("Success.")

        # Flush and check for errors
        self._receive()
        self._check_for_error("_gui_connect")

    def _receive(self):
        response = ""
        self._lastErr = ""

        # Create file from socket for convenience
        # and read each line from it
        file = self._socket.makefile()
        for line in file:
            self._debug("Received: %s" % line)
            # Errors are returned as a string beginning 'ERROR: '
            # Ready is signalled by '__PARAGON__' prompt
            # Anything else is considered a response
            if line.find(ParagonxAPI._PARAGON_ERROR) >= 0:
                # Got an error
                self._lastErr = line[len(ParagonxAPI._PARAGON_ERROR):len(line)]
            elif line.find(ParagonxAPI._PARAGON_READY) >= 0:
                # Got the ready prompt, OK to leave
                break
            else:
                # Got a response. Store it and continue
                response = line
        file.close()

        return response

    if sys.version_info < (3, 0):  # py2
        def _send(self, data):

            self._debug("Sending %s... " % data)
            self._socket.sendall("%s\n" % data)
            self._debug("Done.")
            return self._receive().strip()
    else:  # py3
        def _send(self, data):

            self._debug("Sending %s... " % data)
            self._socket.sendall(bytes("%s\n" % data, "UTF-8"))
            self._debug("Done.")
            return self._receive().strip()

    def _is_connected(self, inst_address):
        response = self._send("paragon.remoteprint(paragon.isconnected(\"%s\"))" % inst_address)
        self._check_for_error("_is_connected")
        return int(response)

    def _build_cmd_from_args(self, *args):
        cmd = ""
        for arg in args:
            # Indexed: 1st char is '#'
            if arg[0] == '#':
                arg = "__IDX____#__" + arg[1:len(arg)]
            # Append argument
            cmd = cmd + "__#__" + arg
        return cmd

    def _instrument_connect(self):
        logging.info("Connecting to instrument %s:%s... " % (self._inst_address, self._inst_port))
        self._send("paragon.connect(\"%s\",\"%s\")" % (self._inst_address, self._inst_port))
        self._check_for_error("_instrument_connect %s:%s" % (self._inst_address, self._inst_port))

    def _instrument_disconnect(self):
        self._send("paragon.disconnect()")
        self._check_for_error("_instrument_disconnect")

    def _query_errors(self):
        self._send("paragon._queryerrors()")
        self._check_for_error("_query_errors")

    def _remote_control_on(self):
        self._send("paragon.on(%s)" % self._rc)
        self._check_for_error("_remote_control_on")

    def _remote_control_off(self):
        self._send("paragon.off()")
        self._check_for_error("_remote_control_off")

    def _set_operating_mode(self, operatingMode):
        self._send("paragon.CSettingParameter(\"__SET____#__OperatingMode__#__%s\")" % operatingMode)
        self._check_for_error("_set_operating_mode %s" % operatingMode)

    def connect(self):
        self._gui_connect()
        self._remote_control_on()

        conn_status = self._is_connected("")
        if conn_status < 2:
            inst_status = self._is_connected(self._inst_address)
            if conn_status == 1 and inst_status == 0:
                curr_ip = self.paragonget("RmtIpAddress")
                self._lastErr = "ERROR: another instrument (%s) is already connected" % curr_ip
                self._check_for_error("connect")
            elif inst_status == 0:
                self._instrument_connect()
                self._connected = True
        else:
            self._connected = True

        if self._connected:
            logging.info("Connected to instrument")
        else:
            if len(self._lastErr) < 1:
                self._lastErr = "ERROR: another instrument is already connected"
            err = self._lastErr
            self.disconnect()
            self._lastErr = err
            self._check_for_error("connect")

    def socketguiconnect(self):
        self._gui_connect()
        self._remote_control_on()

    def instrumentdisconnect(self):
        self._instrument_disconnect()

    def instrumentconnect(self):
        self._instrument_connect()

    ## Disconnnects the currently connected instrument.
    def disconnect(self):
        if self._connected:
            self._instrument_disconnect()
            self._remote_control_off()
            self._socket.close()
            self._socket = None
            self._connected = False

        logging.info("Disconnected.")

    ## Query an instrument setting. Most of the instrument's settings are read
    #  using by this command. (Refer to the remote control manual for the complete list)
    #  @param arg_str required  Setting to query (e.g "Physical LineRate").
    #  @return Setting value.
    #  @throw Exception
    def paragonget(self, arg_str):
        wireCmd = "paragon.CSettingParameter(\"__GET__"
        wireCmd += self._build_cmd_from_args(*shlex.split(arg_str)) + "\")"

        self._send(wireCmd)
        self._check_for_error("paragonget %s" % wireCmd)

        response = self._send("print(paragon.CSettingParameter_resp())")
        self._check_for_error("paragonget %s" % response)

        # Ignore the type ID character at the start of the response
        return response[1:len(response)]

    ## Set an instrument setting. Most of the instrument's settings are controlled
    #  using by this command. (Refer to the remote control manual for the complete list)
    #  @param arg_str required  Setting to set (e.g "Physical LineRate").
    #  @param value   required  The value to set.
    #  @throw Exception
    def paragonset(self, arg_str, value=None):
        wireCmd = "paragon.CSettingParameter(\"__SET__"
        wireCmd += self._build_cmd_from_args(*shlex.split(arg_str))
        if (value != None):
            wireCmd += "__#__" + value
        wireCmd += "\")"

        self._send(wireCmd)
        self._check_for_error("paragonset %s" % wireCmd)

    ## Starts an ALL byte capture.
    #  @throw Exception
    def startpacketcapture(self):
        self._send("paragon.startpacketcapture()")
        self._check_for_error("startpacketcapture")

    ## Starts timing capture.
    #  @throw Exception
    def starttimingcapture(self):
        self._send("paragon.starttimingcapture()")
        self._check_for_error("starttimingcapture")

    ## Stops current capture.
    #  @throw Exception
    def stopcapture(self):
        self._send("paragon.stopcapture()")
        self._check_for_error("stopcapture")

    ## Enables the impairment as configured in the settings.
    #  @throw Exception
    def startimpairment(self):
        self._send("paragon.startimpairment()")
        self._check_for_error("startimpairment")

    ## Disables the impairment as configured in the settings.
    #  @throw Exception
    def stopimpairment(self):
        self._send("paragon.stopimpairment()")
        self._check_for_error("stopimpairment")

    ## Starts Time of Day capture.
    #  @throw Exception
    def starttodcapture(self):
        self._send("paragon.starttodcapture()")
        self._check_for_error("starttodcapture")

    ## Stops Time Of Day capture.
    #  @throw Exception
    def stoptodcapture(self):
        self._send("paragon.stoptodcapture()")
        self._check_for_error("stoptodcapture")

    ## Select the SONET STS1 tributary to impair.
    #  @param trib required  STS1 tributary number.
    #  @throw Exception
    def setsonetowsts1trib(self, trib):
        self._send("paragon.CSettingParameter(\"__SET____#___SonetSts1Trib__#__%s\")" % trib)
        self._check_for_error("setsonetowsts1trib %s" % trib)

    ## Select the SONET VT1.5 tributary to impair.
    #  @param trib required  VT1.5 tributary number.
    #  @throw Exception
    def setsonetowvttrib(self, trib):
        self._send("paragon.CSettingParameter(\"__SET____#___SonetVtTrib__#__%s\")" % trib)
        self._check_for_error("setsonetowvttrib %s" % trib)

    ## Set the SONET delay
    #  @param delay required  Delay in uS.
    #  @throw Exception
    def setsonetdelay(self, delay):
        self._send("paragon.CSettingParameter(\"__SET____#___SonetDelay__#__%s\")" % delay)
        self._check_for_error("setsonetdelay %s" % delay)

    ## Saves the displayed captured data to a file.
    #  @param filename required  Path and filename for a file on the local PC's
    #                            file system. filename must be suffixed with a
    #                            valid filename extension:
    #                            - ".csv"
    #                            - ".cpd"
    #  @throw Exception
    def exportdata(self, filename):
        filename = filename.replace("\\", "/")
        self._send("paragon.exportdata(\"%s\")" % filename)
        self._check_for_error("exportdata %s" % filename)

    ## Loads the captured data from a file.
    #  The importdata is equivalent to using the GUI toolbar menu item File>Import.
    #  This is not port specific and in the bi-directional context is not intended
    #  to be used for loading impairment data for replay.
    #  @param filename required  Path and filename for a file on the local PC's
    #                            file system. filename must be suffixed with a
    #                            valid filename extension:
    #                            - ".csv"
    #                            - ".cpd"
    #  @throw Exception
    def importdata(self, filename):
        filename = filename.replace("\\", "/")
        self._send("paragon.importdata(\"%s\")" % filename)
        self._check_for_error("importdata %s" % filename)

    ## Stores the instrument settings to the file passed in using the filename
    #  parameter. Settings are stored in the file system of the machine hosting
    #  the GUI. The stored settings file can be recalled using the 'recall' command.
    #  If the specified file already exists, then it will be overwritten.
    #  @param filename required  Path and filename for a file on the local PC's
    #                            file system.
    #  @throw Exception
    def store(self, filename):
        filename = filename.replace("\\", "/")
        self._send("saveSettings(\"%s\")" % filename)
        self._check_for_error("store %s" % filename)

    ## Recalls the instrument settings from the file passed in using the filename
    #  parameter. Settings are stored in the file system of the machine hosting
    #  the GUI. A stored settings file can be created by from the Paragon GUI
    #  using Save on the Setup menu.
    #  @param filename required  Path and filename for a file on the local PC's
    #                            file system.
    #  @throw Exception
    def recall(self, filename):
        filename = filename.replace("\\", "/")
        self._send("loadSettings(\"%s\")" % filename)
        self._check_for_error("recall %s" % filename)

    ## Loads the capture data for replay. It will load files specifically to replay
    #  delay profiles against defined message types on defined ports.
    #  The loaded file will be replayed against incoming traffic on the given port.
    #  The importimpairmentdata command is equivalent to using the "Import-Port1" and
    #  "Import-Port2" buttons in the Add Impairments and Delay window
    #  @param port     required  The Ethernet port (1 or 2).
    #  @param filename required  Path to a capture file on the local PC's
    #                            file system.
    #  @throw Exception
    def importimpairmentdata(self, port, filename):
        filename = filename.replace("\\", "/")
        self._send("paragon.importimpairmentdata(\"%s\",\"%s\")" % (port, filename))
        self._check_for_error("importimpairmentdata %s %s" % (port, filename))

    ## Wait for the completion of the current CAT operation.
    #  If a script is waiting for previous open operation or waiting for end of
    #  previous calculation then this command should be always used. It is
    #  recommended to call this after the calls below otherwise there is
    #  possibility to get settings conflict error.
    #  @throw Exception
    def waitforcat(self):
        status = self.paragonget("Cat Status")[0]
        while status == "1":
            status = self.paragonget("Cat Status")[0]
            time.sleep(1)
        print("Wait operation completed")
